const commits = $input.all()[0].json;
const issues = $input.all()[1].json;
const prs = $input.all()[2].json;
const repo = $input.all()[0].context.$node['Set Variables'].json.repo;
const language = $input.all()[0].context.$node['Set Variables'].json.language;

const commitList = commits.map(c => `- ${c.commit.message.split('\n')[0]} (${c.commit.author.name})`).join('\n');
const issueList = issues.filter(i => !i.pull_request).map(i => `- #${i.number}: ${i.title}`).join('\n');
const prList = prs.filter(p => p.merged_at).map(p => `- #${p.number}: ${p.title} (${p.user.login})`).join('\n');

const totalAdditions = prs.filter(p => p.merged_at).reduce((a, p) => a + (p.additions || 0), 0);
const totalDeletions = prs.filter(p => p.merged_at).reduce((a, p) => a + (p.deletions || 0), 0);

return {
  repo,
  language,
  commits: commits.length,
  commitAuthors: [...new Set(commits.map(c => c.commit.author.name))].length,
  issuesClosed: issues.filter(i => !i.pull_request).length,
  prsMerged: prs.filter(p => p.merged_at).length,
  linesAdded: totalAdditions,
  linesRemoved: totalDeletions,
  commitDetails: commitList,
  issueDetails: issueList,
  prDetails: prList,
  weekStart: new Date(Date.now() - 7*24*60*60*1000).toISOString().split('T')[0],
  weekEnd: new Date().toISOString().split('T')[0]
};

