const response = $input.first().json;
const summary = response.content[0].text;
const repo = $input.first().context.$node['Set Variables'].json.repo;
const weekStart = $input.first().context.$node['Aggregate Data'].json.weekStart;
const weekEnd = $input.first().context.$node['Aggregate Data'].json.weekEnd;

const webhookContent = {
  embeds: [{
    title: `Weekly Dev Summary — ${repo}`,
    description: `Week of ${weekStart} – ${weekEnd}`,
    color: 3447003,
    fields: [{
      name: 'Summary',
      value: summary.substring(0, 2048),
      inline: false
    }],
    footer: { text: 'Generated by n8n + Claude API' },
    timestamp: new Date().toISOString()
  }]
};

return { webhookUrl: $input.first().context.$node['Set Variables'].json.discordWebhook, content: webhookContent };
